/* 世界锚点：必须是内容尺寸 */
.BossHealthRoot {
    flow-children: none;
    width: 540px; /* 440 + 4 + 96 */
    height: 40px;
    horizontal-align: left;
    vertical-align: top;
    position: 0px 0px 0px;
    overflow: noclip;
}

.BossHealthRoot.EliteHealthBar {
    width: 270px; /* 220 + 2 + 48 */
    height: 20px;
}

/* 真正的UI框 */
.BossHealthFrame {
    flow-children: none;
    width: 540px;
    height: 40px; /* 16px 内容 + 2px 边框 * 2 */
    horizontal-align: left;
    vertical-align: top;
    position: 0px 0px 0px;
    border: 0px solid #2a0e03;
    border-radius: 8px;
    overflow: noclip;
}

/* 血条容器 */
#SegmentsContainer {
    width: 440px;
    height: 32px;
    flow-children: none;
    horizontal-align: left;
    vertical-align: top;
    position: 0px 4px 0px;
    border: 6px solid #391002;
    border-radius: 8px; /* outer radius */
    background-color: #000000cc;
    overflow: clip;
}

#MultiplierContainer {
    width: 96px;
    height: 32px;
    horizontal-align: left;
    vertical-align: top;
    position: 444px 4px 0px;
    flow-children: none;
    overflow: noclip;
}

/* 单条血条容器 */
.HealthSegment {
    width: 100%;
    height: 32px;
    overflow: clip;
    flow-children: none;
    border-radius: 2px; /* inner radius = outer(8) - border(6) */
}

/* 下一层底色 */
.HealthUnderfill {
    width: 100%;
    height: 100%;
    opacity: 1;
    z-index: 0;
    border-radius: 2px;
}

/* 当前层血量 */
.HealthFill {
    width: 0%;
    height: 100%;
    z-index: 1;
    border-radius: 2px;
    transition-property: width;
    transition-duration: 0.5s;
    transition-timing-function: cubic-bezier(0.05, 0.9, 0.1, 1);
}

/* 倍率 */
#MultiplierLabel {
    horizontal-align: center;
    vertical-align: center;
    width: 100%;
    text-align: center;
    font-size: 38px;
    color: #ffd34a;
    font-weight: bold;
    text-overflow: noclip;
    overflow: noclip;
    text-shadow:
        -2px 0px 0px #1f0b01,
        2px 0px 0px #1f0b01,
        0px -2px 0px #1f0b01,
        0px 2px 0px #1f0b01,
        0px 0px 4px #1f0b01;
}

/* Elite: 整体尺寸缩小 50%（显式尺寸，不走 transform） */
.BossHealthRoot.EliteHealthBar .BossHealthFrame {
    width: 270px;
    height: 20px;
    border-width: 0px;
    border-radius: 4px;
}

.BossHealthRoot.EliteHealthBar #SegmentsContainer {
    width: 220px;
    height: 16px;
    position: 0px 2px 0px;
    border-width: 3px;
    border-radius: 4px;
}

.BossHealthRoot.EliteHealthBar .HealthSegment {
    height: 16px;
    border-radius: 1px;
}

.BossHealthRoot.EliteHealthBar .HealthUnderfill {
    border-radius: 1px;
}

.BossHealthRoot.EliteHealthBar .HealthFill {
    border-radius: 1px;
}

/* 右侧数字变化动效 */
#MultiplierLabel.MultiplierPulse {
    animation-name: BossMultiplierPulse;
    animation-duration: 0.22s;
    animation-iteration-count: 1;
    animation-timing-function: ease-out;
}

@keyframes 'BossMultiplierPulse' {
    0% {
        pre-transform-scale2d: 1.0;
        brightness: 1.0;
        text-shadow:
            -2px 0px 0px #1f0b01,
            2px 0px 0px #1f0b01,
            0px -2px 0px #1f0b01,
            0px 2px 0px #1f0b01,
            0px 0px 4px #1f0b01;
    }
    40% {
        pre-transform-scale2d: 2;
        brightness: 1.2;
        text-shadow:
            -2px 0px 0px #1f0b01,
            2px 0px 0px #1f0b01,
            0px -2px 0px #1f0b01,
            0px 2px 0px #1f0b01,
            0px 0px 8px #ffd34aaa,
            0px 0px 14px #ffd34a66;
    }
    100% {
        pre-transform-scale2d: 1.0;
        brightness: 1.0;
        text-shadow:
            -2px 0px 0px #1f0b01,
            2px 0px 0px #1f0b01,
            0px -2px 0px #1f0b01,
            0px 2px 0px #1f0b01,
            0px 0px 4px #1f0b01;
    }
}
.BossHealthRoot.EliteHealthBar #MultiplierContainer {
    width: 48px;
    height: 16px;
    position: 222px 2px 0px;
    overflow: noclip;
}

.BossHealthRoot.EliteHealthBar #MultiplierLabel {
