function IsBossHealthDebug()
{
  var cfg = GameUI && GameUI.CustomUIConfig ? GameUI.CustomUIConfig() : null;
  return !!(cfg && cfg.boss_health_debug);
}

function ResolveWorldPanelSize(wp)
{
  var data = wp && wp.data ? wp.data : null;
  var fixedW = data ? Number(data.worldpanel_fixed_width) : 0;
  var fixedH = data ? Number(data.worldpanel_fixed_height) : 0;
  if (fixedW > 0 && fixedH > 0)
  {
    return {
      w: fixedW,
      h: fixedH,
      mode: "fixed",
    };
  }

  var useDesiredSize = !!(data && data.worldpanel_size_mode === "desired");
  var panelW = useDesiredSize ? (wp.panel.desiredlayoutwidth || wp.panel.actuallayoutwidth) : wp.panel.actuallayoutwidth;
  var panelH = useDesiredSize ? (wp.panel.desiredlayoutheight || wp.panel.actuallayoutheight) : wp.panel.actuallayoutheight;
  return {
    w: panelW,
    h: panelH,
    mode: useDesiredSize ? "desired" : "actual",
  };
}

// panel deletion call?
// Delete call to server for cleanup

function WorldPanelChange(id, changes, dels)
{
  //$.Msg("change ", id, ' -- ', changes, ' -- ', dels);
  for (var k in changes){
    var wp = panels[k];
    if (!wp){
      wp = {};
      panels[k] = wp;
    }

    if (changes[k].layout !== wp.layout){
      if (wp.panel)
        wp.panel.DeleteAsync(0);

      wp.panel = $.CreatePanel( "Panel", $.GetContextPanel(), "" );
      wp.panel.BLoadLayout(changes[k].layout, false, false);
      wp.panel.WorldPanel = wp;
      wp.panel.OnEdge = false;
      wp.panel.OffScreen = false;
      wp.panel.Data = wp.data;
      wp.panel.DeleteWorldPanel = function(pan){ 
        return function(){
          pan.DeleteAsync(0);
          delete panels[k];
        }
      }(wp.panel);

    }

    for (j in changes[k]){
      if (j == "position"){
        wp[j] = changes[k][j].split(' ');
        wp[j] = [parseFloat(wp[j][0]), parseFloat(wp[j][1]), parseFloat(wp[j][2])]
      }
      else if (j == "data"){
        wp.panel.Data = changes[k][j];
        wp[j] = changes[k][j];
      }
      else
        wp[j] = changes[k][j];
    }
    
    //wp.dirty = true;
    wp.offsetX = wp.offsetX || 0;
    wp.offsetY = wp.offsetY || 0;
    wp.entityHeight = wp.entityHeight || 0;
    wp.hAlign = wp.hAlign || HA_CENTER;
    wp.vAlign = wp.vAlign || VA_BOTTOM;
    wp.edge = wp.edge || -1;
    wp.seen = wp.entity ? Entities.IsValidEntity(wp.entity) : null;

  }

  for (var k in dels){
    panels[k].panel.DeleteAsync(0);
    delete panels[k];
  }
}

function PositionPanels()
{
  var now = Game.GetGameTime();
  var dt = lastPositionTick > 0 ? Math.max(now - lastPositionTick, 0) : 0;
  lastPositionTick = now;
  var alpha = dt > 0 ? Math.min(1, dt * PANEL_SMOOTHING_SPEED) : 1;
  //$.Msg(Object.keys(panels).length);
  for (var k in panels){
    var wp = panels[k];
    var pos = wp.position;
    if (!pos){
      if (!Entities.IsValidEntity(wp.entity)){
        if (wp.seen){
          panels[k].panel.DeleteAsync(0);
          delete panels[k];
          continue;
        }
        else{
          continue;
        }
      }


      wp.seen = true;

      pos = Entities.GetAbsOrigin(wp.entity);
      if (entities.indexOf(wp.entity) === -1){
        wp.panel.visible = false;
