(function () {
    "use strict";

    var POPUP_DURATION = 1.15;
    var MAX_PER_FRAME = 100;
    var POOL_SIZE = 400;
    var MAX_ACTIVE = 400;
    var JITTER_X = 20;
    var JITTER_Y = 10;
    var Z_OFFSET = 180;
    var RISE_TIME = 0.35;
    var PEAK_HEIGHT = 52;
    var HORIZONTAL_SPEED = 50;
    var CRIT_RISE_TIME = 0.3;
    var CRIT_PEAK_HEIGHT = 78;
    var CRIT_HORIZONTAL_SPEED = 90;
    var CRIT_DURATION = 1.25;
    var WALL_RISE_TIME = 0.38;
    var WALL_PEAK_HEIGHT = 92;
    var WALL_HORIZONTAL_SPEED = 70;
    var WALL_DURATION = 1.35;
    var WALL_CRIT_RISE_TIME = 0.42;
    var WALL_CRIT_PEAK_HEIGHT = 120;
    var WALL_CRIT_HORIZONTAL_SPEED = 95;
    var WALL_CRIT_DURATION = 1.5;
    var FADE_SCALE = 0

    var root = $.GetContextPanel();
    var layer = root.FindChildInLayoutFile("DamagePopupsLayer");

    var pool = [];
    var active = [];
    var queue = [];

    function trimTrailingZero(str) {
        if (str.indexOf(".") === -1) {
            return str;
        }
        while (str.length > 0 && str[str.length - 1] === "0") {
            str = str.slice(0, -1);
        }
        if (str.length > 0 && str[str.length - 1] === ".") {
            str = str.slice(0, -1);
        }
        return str;
    }

    function formatNumberShort(value) {
        var absValue = Math.abs(value);
        var sign = value < 0 ? "-" : "";

        if (absValue < 1000) {
            return sign + Math.floor(absValue).toString();
        }

        if (absValue >= 1000000) {
            var numM = absValue / 1000000;
            return sign + trimTrailingZero(numM.toFixed(1)) + "m";
        }

        var numK = absValue / 1000;
        return sign + trimTrailingZero(numK.toFixed(1)) + "k";
    }

    function createPanel() {
        var panel = $.CreatePanel("Label", layer, "");
        panel.AddClass("DamagePopup");
        panel.hittest = false;
        panel.visible = false;
        return panel;
    }

    function initPool() {
        for (var i = 0; i < POOL_SIZE; i++) {
            pool.push(createPanel());
        }
    }

    function acquirePanel() {
        if (pool.length > 0) {
            return pool.pop();
        }

        if (active.length >= MAX_ACTIVE) {
            return null;
        }

        return createPanel();
    }

    function releasePanel(popup) {
        popup.panel.visible = false;
        popup.panel.RemoveClass("DamagePopup--Active");
        popup.panel.SetHasClass("DamagePopup--Crit", false);
        popup.panel.SetHasClass("DamagePopup--Enhance", false);
        popup.panel.SetHasClass("DamagePopup--Heal", false);
        popup.panel.SetHasClass("DamagePopup--Gold", false);
        popup.panel.SetHasClass("DamagePopup--Block", false);
        popup.panel.SetHasClass("DamagePopup--Wall", false);
        popup.panel.SetHasClass("DamagePopup--WallCrit", false);
        pool.push(popup.panel);
    }

    function getScreenMetrics() {
        var sw = 0;
        var sh = 0;
        if (GameUI && GameUI.CustomUIConfig) {
            var cfg = GameUI.CustomUIConfig();
            if (cfg) {
                sw = cfg.screenwidth || 0;
                sh = cfg.screenheight || 0;
            }
        }
        if ((!sw || !sh) && root) {
            sw = root.actuallayoutwidth || sw;
            sh = root.actuallayoutheight || sh;
        }
        if ((!sw || !sh) && GameUI && GameUI.GetScreenSize) {
            var size = GameUI.GetScreenSize();
            if (size && size.length >= 2) {
                sw = size[0];
                sh = size[1];
            }
        }
        return { sw: sw, sh: sh };
    }

    function updatePosition(popup) {
        if (!Entities.IsValidEntity(popup.entindex)) {
            popup.panel.visible = false;
            return;
        }

        var origin = Entities.GetAbsOrigin(popup.entindex);
        var worldX = origin[0];
        var worldY = origin[1];
        var worldZ = origin[2] + popup.zOffset;

        var screenX = Game.WorldToScreenX(worldX, worldY, worldZ);
        var screenY = Game.WorldToScreenY(worldX, worldY, worldZ);

        var metrics = getScreenMetrics();
        var sw = metrics.sw;
        var sh = metrics.sh;
        if (screenX < 0 || screenY < 0 || (sw > 0 && screenX > sw) || (sh > 0 && screenY > sh)) {
            popup.panel.visible = false;
            return;
        }

        var scale = 1.0;
        if (sh > 0) {
            scale = 1080 / sh;
        }

        var now = Game.Time();
        var elapsed = Math.max(0, now - popup.startTime);
        var t = Math.min(elapsed, popup.duration);

        var riseTime = popup.riseTime;
        var peakHeight = popup.peakHeight;
        var gravity = (2 * peakHeight) / (riseTime * riseTime);
        var v0 = gravity * riseTime;
        var yOffset = (v0 * t) - (0.5 * gravity * t * t);
        var xOffset = popup.vx * t;

        var x = screenX * scale + popup.jitterX + xOffset;
        var y = screenY * scale + popup.jitterY - yOffset;

        if (t >= riseTime) {
            var fallT = t - riseTime;
            var fallDuration = Math.max(0.05, popup.duration - riseTime);
            var fade = 1 - Math.min(1, fallT / fallDuration);
            popup.panel.style.opacity = fade.toFixed(3);
            var scale = 1 - (1 - FADE_SCALE) * (1 - fade);
            popup.panel.style.transform = "scale3d(" + scale.toFixed(3) + ", " + scale.toFixed(3) + ", 1)";
        } else {
            popup.panel.style.opacity = "1";
            popup.panel.style.transform = "scale3d(1, 1, 1)";
        }

        popup.panel.visible = true;
        popup.panel.SetPositionInPixels(x, y, 0);
    }

    function spawnPopup(data) {
        var panel = acquirePanel();
        if (!panel) {
            return;
        }

        var amount = data.amount || 0;
        var kind = data.kind || "default";

        var isCrit = kind === "crit";
        var isWall = kind === "wall" || kind === "wall_crit";
        var isWallCrit = kind === "wall_crit";
        var riseTime = isWall ? (isWallCrit ? WALL_CRIT_RISE_TIME : WALL_RISE_TIME) : (isCrit ? CRIT_RISE_TIME : RISE_TIME);
        var peakHeight = isWall ? (isWallCrit ? WALL_CRIT_PEAK_HEIGHT : WALL_PEAK_HEIGHT) : (isCrit ? CRIT_PEAK_HEIGHT : PEAK_HEIGHT);
        var duration = isWall ? (isWallCrit ? WALL_CRIT_DURATION : WALL_DURATION) : (isCrit ? CRIT_DURATION : POPUP_DURATION);
        var hSpeed = isWall ? (isWallCrit ? WALL_CRIT_HORIZONTAL_SPEED : WALL_HORIZONTAL_SPEED) : (isCrit ? CRIT_HORIZONTAL_SPEED : HORIZONTAL_SPEED);
        var popup = {
            panel: panel,
            entindex: data.entindex,
            startTime: Game.Time(),
            duration: duration,
            endTime: Game.Time() + duration,
            jitterX: (Math.random() - 0.5) * JITTER_X,
            jitterY: (Math.random() - 0.5) * JITTER_Y,
            zOffset: Z_OFFSET,
            vx: (Math.random() - 0.5) * hSpeed,
            riseTime: riseTime,
            peakHeight: peakHeight,
        };

        panel.text = formatNumberShort(amount);
        panel.style.opacity = "1";
        panel.SetHasClass("DamagePopup--Crit", kind === "crit");
        panel.SetHasClass("DamagePopup--Enhance", kind === "enhance");
        panel.SetHasClass("DamagePopup--Heal", kind === "heal");
        panel.SetHasClass("DamagePopup--Gold", kind === "gold");
        panel.SetHasClass("DamagePopup--Block", kind === "block");
        panel.SetHasClass("DamagePopup--Wall", kind === "wall");
        panel.SetHasClass("DamagePopup--WallCrit", kind === "wall_crit");

        panel.RemoveClass("DamagePopup--Active");
        panel.AddClass("DamagePopup--Active");

        updatePosition(popup);
        active.push(popup);
    }

    function onDamagePopup(data) {
        if (!data || data.entindex === undefined) {
            return;
        }

        queue.push(data);
    }

    function tick() {
        var now = Game.Time();

        for (var i = active.length - 1; i >= 0; i--) {
            var popup = active[i];
            if (popup.endTime <= now) {
                releasePanel(popup);
                active.splice(i, 1);
            } else {
                updatePosition(popup);
            }
        }

        var count = Math.min(queue.length, MAX_PER_FRAME, pool.length + (MAX_ACTIVE - active.length));
        for (var j = 0; j < count; j++) {
            spawnPopup(queue.shift());
        }

        $.Schedule(0.0, tick);
    }

    function init() {
        if (!layer) {
            return;
        }

        initPool();
        GameEvents.Subscribe("dzsj_damage_popup", onDamagePopup);
        tick();
    }

    init();
})();

